def compute(vars):
    interest_expense = vars["v1"]
    interest_income = vars["v2"]

    if interest_income == 0:
        return None

    ratio = interest_expense / interest_income
    return {
        "value": ratio,
        "trace": {
            "interest_expense": interest_expense,
            "interest_income": interest_income,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
